const helpers=`const assert=(value,message)=>{if(window.__rw26QA)__rw26QA.assertions=(__rw26QA.assertions||0)+1;if(!value)throw new Error(message)};const wait=async (fn,limit=400)=>{for(let i=0;i<limit;i++){if(fn())return;await new Promise(r=>setTimeout(r,15));}throw new Error('Local UI wait expired')};const panel=()=>document.querySelector('.rw26-inline');const box=()=>document.querySelector('.rw26-source');const fill=text=>{box().value=text;box().dispatchEvent(new Event('input',{bubbles:true}));};const clean=()=>{assert(__rw26QA.forbiddenNetwork.length===0,'No unmocked API mutation');assert(__rw26QA.submits===0,'No native form publication');assert(__rw26QA.errors.length===0,'No uncaught JavaScript errors: '+__rw26QA.errors.join(';'));};`;
