(async()=>{try{await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));origin='http://127.0.0.1:'+server.address().port;await driver.start(origin);report.browserVersion=driver.version;await(loaderMode?runLoader():runBasic());report.completedAt=new Date().toISOString();report.blockedOutsideRequests=driver.blocked?.length||0;save();}catch(e){report.runnerError=String(e.stack||e);save();process.exitCode=1;}finally{await driver.close();server.closeAllConnections?.();await new Promise(resolve=>server.close(resolve));if(report.tests.some(t=>!t.passed))process.exitCode=1;}})();
